                public function setSchema($data) {
                    $this->schemas[] = json_encode($data, JSON_PRETTY_PRINT | JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE);
                }

                public function getSchema() {
                    return $this->schemas;
                }

{% if schemas_org %}
{% for schema in schemas_org %}
<script type="application/ld+json">
{{ schema }}
</script>
{% endfor %}
{% endif %}

$schema = array('@context'=>'http://schema.org');
$schema['@type'] = 'Webpage';
$schema['headline'] = $product_info['meta_title'];
$schema['@id'] = $this->url->link('product/product' . '&product_id=' . $this->request->get['product_id']);
$schema['thumbnailUrl'] = "";
$schema['dateCreated'] = "";
$schema['name'] = "NatureLoc";
$schema['description'] = $product_info['meta_description'];
$schema['publisher'] = "NatureLoc";
$schema['creator'] = [];
$schema['keywords'] = array($product_info['meta_keyword']);
$this->document->setSchema($schema);
unset($schema);
$schema = array('@context'=>'http://schema.org');
$schema['@type'] = 'Product';
$schema['name'] = $product_info['name'];
if($product_info['meta_description']){
$schema['description'] = $product_info['meta_description'];
}
$schema_images = array();
if ($product_info['image']) {
   $schema_images = array($this->model_tool_image->resize($product_info['image'], $this->config->get('theme_' . $this->config->get('config_theme') . '_image_popup_width'), $this->config->get('theme_' . $this->config->get('config_theme') . '_image_popup_height')));
   foreach ($results as $result) {
    array_push($schema_images, $this->model_tool_image->resize($result['image'], $this->config->get('theme_' . $this->config->get('config_theme') . '_image_popup_width'), $this->config->get('theme_' . $this->config->get('config_theme') . '_image_popup_height')));
}
}
$schema['image'] = $schema_images;
if ($product_info['mpn']) {
    $schema['mpn'] = $product_info['mpn'];
}
if ($product_info['sku']) {
    $schema['sku'] = $product_info['sku'];
}
if ($product_info['sku']) {
    $schema['mpn'] = $product_info['sku'];
}
if ($product_info['model']) {
    $schema['model'] = $product_info['model'];
}
$schema['offers']['@type'] = 'Offer';
if ($product_info['special']) {
    $schema['offers']['price'] = $this->tax->calculate($product_info['special'], $product_info['tax_class_id'], $this->config->get('config_tax'));
} else {
    $schema['offers']['price'] = $this->tax->calculate($product_info['price'], $product_info['tax_class_id'], $this->config->get('config_tax'));
}
$schema['offers']['priceCurrency'] = $this->config->get('config_currency');
$schema['offers']['url'] = $this->url->link('product/product' . '&product_id=' . $this->request->get['product_id']);
if ($product_info['quantity'] >= 0) {
    $schema['offers']['availability'] = 'http://schema.org/InStock';
} else {
    $schema['offers']['availability'] = 'http://schema.org/OutOfStock';
}
if ($product_info['special_date_end']) {
    $schema['offers']['priceValidUntil'] = $product_info['special_date_end'];
}
//else{
    //$schema['offers']['priceValidUntil'] = '3000-01-01';
//}
if ((int)$product_info['reviews'] > 0) {
    $schema['aggregateRating']['@type'] = 'AggregateRating';
    $schema['aggregateRating']['ratingValue'] = (int)$product_info['rating'];
    $schema['aggregateRating']['reviewCount'] = (int)$product_info['reviews'];
}
if ($product_info['manufacturer']) {
    $schema['brand']['@type'] = 'Brand';
    $schema['brand']['name'] = $product_info['manufacturer'];
    $schema['brand']['url'] = $this->url->link('product/manufacturer/info', 'manufacturer_id=' . $product_info['manufacturer_id']);
}
$reviews = $this->model_catalog_review->getReviewsByProductId($this->request->get['product_id'], (1 - 1) * 5, 5);
if ($reviews) {
    foreach ($reviews as $review) {

        $reviewRating=array('@type'=>"Rating",'ratingValue'=>4,'bestRating'=>5);
        $author=array("@type"=>"Person","name"=>$review['author']);
        $schema['review'][] = array('@type' => 'Review','reviewRating'=>$reviewRating,'author' =>$author);
        //'datePublished' => date($this->language->get('date_format_short'), strtotime($review['date_added'])), 'description' => strip_tags(html_entity_decode($review['text'], ENT_QUOTES, 'UTF-8'));
    }
}
$this->document->setSchema($schema);
unset($schema);
$schema = array('@context'=>'http://schema.org');
$schema['@type'] = 'BreadcrumbList';
$number = 1;
foreach ($data['breadcrumbs'] as $breadcrumb) {
    if ($number == 1) {
        $text = 'Home';
    } else {
        $text = $breadcrumb['text'];
    }
    $schema['itemListElement'][] = array('@type' => 'ListItem', 'position' => $number, 'item' => array('@id' => $breadcrumb['href'], 'name' => $text));
    $number++;
}
